const assert = require("node:assert/strict");
const fs = require("node:fs");
const path = require("node:path");

const root = path.resolve(__dirname, "..");
const outputPath = path.join(root, "webresource.html");

assert.ok(fs.existsSync(outputPath), "webresource.html deve ser gerado");

const html = fs.readFileSync(outputPath, "utf8");
assert.ok(html.includes("<style>"), "CSS deve estar inline");
assert.ok(html.includes("window.XlsxImportCore"), "core XLSX deve estar inline");
assert.ok(html.includes("function openXlsxImportPicker"), "app.js deve estar inline");
assert.ok(html.includes("id=\"tab-panel-import\""), "aba de importacao deve estar no bundle");
assert.ok(!html.includes("id=\"importReviewOverlay\""), "overlay antigo de importacao nao deve estar no bundle");
assert.ok(!html.includes("id=\"importSaveAll\""), "bundle nao deve exibir botao de salvar todos validos");
assert.ok(!html.includes("Salvar todos vÃ¡lidos"), "bundle nao deve conter texto salvar todos validos");
assert.ok(!html.includes("Agendar confirmados"), "bundle nao deve conter acao de agendar confirmados em lote");
assert.ok(!html.includes("id=\"importReviewCancel\""), "bundle nao deve exibir botao voltar aos detalhes");
assert.ok(!html.includes("Voltar aos detalhes"), "bundle nao deve conter texto voltar aos detalhes");
assert.ok(!html.includes("saveAllValidImportedTrechos"), "bundle nao deve conter handler de salvar todos validos");
assert.ok(!html.includes("closeImportReview"), "bundle nao deve conter handler de voltar aos detalhes");
assert.ok(!html.includes("function createManualImportedTrecho"), "bundle nao deve criar servico manual dentro da PG");
assert.ok(!html.includes("add-manual-trecho"), "bundle nao deve expor acao de adicionar servico manual");
assert.ok(!html.includes("Adicionar serviço manual"), "bundle nao deve exibir botao de servico manual");
assert.ok(html.includes("clienteLabel: \"Embraer\""), "bundle deve fixar Embraer como cliente padrao do import");
assert.ok(html.includes("function persistMockPassengerRecord"), "bundle deve persistir passageiros no mock local");
assert.ok(html.includes("async function ensureXlsxLibrary"), "bundle deve carregar SheetJS sob demanda");
assert.ok(html.includes('id="xlsxLibrarySource" type="application/x-formulario-vendor"'), "bundle deve manter SheetJS inerte no boot");
assert.ok(html.includes("cr40f_idexterno"), "bundle deve conter o campo externo PG");
assert.ok(html.includes("split-trecho"), "bundle deve expor acao Split na revisao de importacao");
assert.ok(html.includes("importedTrechoReturnDateTimeLocal"), "bundle deve editar horario previsto de retorno importado");
assert.ok(html.includes("import-decision-panel"), "bundle deve conter painel de decisao operacional da PG");
assert.ok(html.includes("Interpretação da PG"), "bundle deve apresentar interpretacao operacional generica");
assert.ok(html.includes("Multi-coleta"), "bundle deve reconhecer PG com coletas sequenciais");
assert.ok(!html.includes("Manter 1 OS"), "bundle nao deve exibir botao de manter 1 OS");
assert.ok(html.includes("É o mesmo carro"), "bundle deve permitir mesclar trechos selecionados da mesma PG");
assert.ok(html.includes("toggle-same-car-selection"), "bundle deve permitir selecionar trechos para merge");
assert.ok(html.includes("merge-same-car"), "bundle deve expor acao de merge mesmo carro");
assert.ok(html.includes("Separar ida/busca"), "bundle deve expor Split com linguagem operacional");
assert.ok(html.includes("keep-waiting"), "bundle deve permitir registrar manter espera");
assert.ok(html.includes("function renderImportReviewFilters"), "bundle deve transformar importReviewStats em filtros");
assert.ok(html.includes("buildImportReviewFilterButton(\"Todos\""), "bundle deve conter filtro Todos");
assert.ok(html.includes("buildImportReviewFilterButton(\"Validados\""), "bundle deve conter filtro Validados");
assert.ok(html.includes("buildImportReviewFilterButton(\"Pendentes\""), "bundle deve conter filtro Pendentes");
assert.ok(html.includes("buildImportReviewFilterButton(\"Ignorados\""), "bundle deve conter filtro Ignorados");
assert.ok(html.includes("import-filter-count"), "bundle deve exibir contador pequeno nos filtros");
assert.ok(!html.includes("function importStat"), "bundle nao deve renderizar cards passivos antigos no importReviewStats");
assert.ok(!html.includes("importStat(\"Linhas\""), "bundle nao deve manter cards Linhas/PGs/Trechos no header");
assert.ok(html.includes("function buildImportInspectorReviewActions"), "bundle deve expor Validar/Ignorar no inspector");
assert.ok(html.includes("const hasKeepAction = hasReturn && !isMultiPickup && !isSeparable"), "bundle nao deve exibir Manter espera em servico separavel");
assert.ok(html.includes(".import-inspector-head > div:not(.import-inspector-actions)"), "bundle nao deve empilhar botoes do inspector pela regra do titulo");
assert.ok(html.includes("flex-wrap: nowrap;"), "bundle deve manter botoes do inspector em linha");
assert.ok(html.includes("--import-inspector-action-height: 32px;"), "bundle deve fixar altura comum para editar, validar e ignorar");
assert.ok(html.includes("height: var(--import-inspector-action-height);"), "bundle deve aplicar altura comum aos botoes do inspector");
assert.ok(html.includes(".import-inspector-actions .primary-action[data-import-action=\"confirm-review\"]"), "bundle deve ter estilo verde para Validar");
assert.ok(!html.includes("manual-operational-review"), "bundle nao deve expor botao de revisar manual");
assert.ok(!html.includes("Revisar manual"), "bundle nao deve exibir texto Revisar manual");
assert.ok(html.includes("Validar"), "bundle deve exibir acao Validar");
assert.ok(html.includes("Ignorar"), "bundle deve exibir acao Ignorar");
assert.ok(html.includes("function getValidatedImportTrechos"), "bundle deve separar servicos validados da fila principal");
assert.ok(html.includes("status !== statuses.CONFIRMED && status !== statuses.SAVED && status !== statuses.IGNORED"), "bundle nao deve deixar resolvidos na fila principal");
assert.ok(html.includes("buildImportCollapsedStatusList(\"Validados\""), "bundle deve ter grupo fechado de Validados");
assert.ok(html.includes("buildImportCollapsedStatusList(\"Ignorados\""), "bundle deve ter grupo fechado de Ignorados");
assert.ok(html.includes("openValidated: activeFilter === importReviewFilters().VALIDATED"), "bundle deve abrir Validados ao filtrar");
assert.ok(html.includes("openIgnored: activeFilter === importReviewFilters().IGNORED"), "bundle deve abrir Ignorados ao filtrar");
assert.ok(html.includes("import-collapsed-list"), "bundle deve conter listas fechadas de resolvidos");
assert.ok(html.includes("import-ignored-list"), "bundle deve exibir lista de ignorados");
assert.ok(html.includes("import-timeline"), "bundle deve conter timeline de saida e retorno");
assert.ok(html.includes("Janela da PG"), "bundle deve explicar a janela operacional da PG");
assert.ok(html.includes("function getRecordIdFromHostContext"), "bundle deve ler id do formulario pai no Model-driven App");
assert.ok(html.includes("selectedItemReferences"), "bundle deve aceitar data de comando com selecao da grid");
assert.ok(html.includes("clearDraftSnapshot(false);"), "bundle deve iniciar sem rascunho local anterior");
assert.ok(!html.includes("await restoreDraftSnapshot();"), "bundle nao deve restaurar rascunho ao abrir o RW");
assert.ok(html.includes("buildRecurringRetornoPrevisto"), "bundle deve recalcular previsao de retorno por data recorrente");
assert.ok(!html.includes("Agendar Retorno' ao mesmo tempo"), "bundle deve permitir Retorno e Repetir juntos na criacao");
assert.ok(html.includes("activationGuardOverlay"), "bundle deve conter popup para abas preenchidas sem ativar");
assert.ok(html.includes(".tab.is-pending::after"), "bundle deve conter bolinha amarela para aba pendente");
assert.ok(html.includes("id=\"closeRwButton\""), "bundle deve conter botao sutil para fechar o RW");
assert.ok(html.includes("pageType: \"entitylist\""), "bundle deve voltar para a lista da tabela Geral");
assert.ok(html.includes("entityName: CONFIG.entities.reserva"), "bundle deve navegar para a entidade real da Geral");
assert.ok(html.includes(".passenger-edit-field textarea.passenger-edit-control"), "bundle deve conter regra dos textareas de passageiro");
assert.ok(html.includes("resize: vertical;"), "bundle deve manter textareas redimensionaveis");
assert.ok(html.includes("max-height: none;"), "bundle deve permitir crescimento vertical dos textareas");
assert.ok(!html.includes(".import-trecho.is-locked [data-import-copy] textarea[readonly]"), "bundle nao pode bloquear pointer events de textarea importado readonly");
assert.ok(!html.includes(".import-trecho.is-duplicated [data-import-copy] textarea[readonly]"), "bundle nao pode bloquear pointer events de textarea duplicado readonly");
assert.ok(!html.includes('<link rel="stylesheet" href="styles.css"'), "bundle nao deve depender de styles.css externo");
assert.ok(!html.includes('<script src="app.js"'), "bundle nao deve depender de app.js externo");
assert.ok(!html.includes('<script src="vendor/xlsx.full.min.js"'), "bundle nao deve depender de SheetJS externo");
assert.ok(!html.includes('<script src="scripts/xlsx_import_core.js"'), "bundle nao deve depender do core externo");
assert.ok(!html.includes("<!-- INLINE_"), "bundle nao deve manter placeholders internos");

console.log("webresource_bundle: ok");
